def generateSentences(synonyms: list[list[str]], text: str) -> list[str]:
    from collections import defaultdict, deque

    # Build adjacency list for synonym groups
    graph = defaultdict(list)
    all_words = set()

    for a, b in synonyms:
        graph[a].append(b)
        graph[b].append(a)
        all_words.add(a)
        all_words.add(b)

    # Find connected components using BFS/DFS
    visited = set()
    groups = []

    def bfs(start):
        queue = deque([start])
        visited.add(start)
        group = [start]

        while queue:
            word = queue.popleft()
            for neighbor in graph[word]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
                    group.append(neighbor)

        return sorted(group)  # Return sorted to ensure lexicographical order

    # Group all synonyms together
    for word in all_words:
        if word not in visited:
            groups.append(bfs(word))

    # Map each synonym to its group index
    word_to_group = {}
    for i, group in enumerate(groups):
        for word in group:
            word_to_group[word] = i

    # Split text into words
    words = text.split()

    # Generate all combinations using backtracking
    result = []

    def backtrack(index: int, current_sentence: list[str]):
        if index == len(words):
            result.append(" ".join(current_sentence))
            return

        word = words[index]

        # If the word is not in any synonym group, just use it as-is
        if word not in word_to_group:
            backtrack(index + 1, current_sentence + [word])
        else:
            # Try all synonyms from the same group
            group_index = word_to_group[word]
            for synonym in groups[group_index]:
                backtrack(index + 1, current_sentence + [synonym])

    backtrack(0, [])
    return result

