def removeStones(stones: List[List[int]]) -> int:
    if not stones:
        return 0

    parent = {}

    def find(x):
        if x != parent.setdefault(x, x):
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    for x, y in stones:
        # Union rows and columns
        union(x, ~y)  # Using ~y to distinguish between row and column indices

    return len(stones) - len(set(find(x) for x, _ in stones))

